package ai.taskforge.knowledge;
import ai.taskforge.domain.*; import ai.taskforge.repo.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*; import java.util.stream.*;
@Service public class KnowledgeService { private final DocumentChunkRepository chunks;private final EmbeddingProvider embeddings; public KnowledgeService(DocumentChunkRepository c,EmbeddingProvider e){chunks=c;embeddings=e;} @Transactional public void index(Document doc){chunks.deleteByDocumentId(doc.getId());var words=doc.getExtractedText().replaceAll("\\s+"," ").trim();for(int offset=0,index=0;offset<words.length();index++){int end=Math.min(offset+800,words.length());if(end<words.length()){int split=words.lastIndexOf(' ',end);if(split>offset+150)end=split;}String content=words.substring(offset,end).trim();if(!content.isBlank())chunks.save(new DocumentChunk(doc,index,content,encode(embeddings.embed(content))));offset=end;while(offset<words.length()&&words.charAt(offset)==' ')offset++;}} public List<Hit> search(String query,int limit){var q=embeddings.embed(query);return chunks.findAll().stream().map(c->new Hit(c.getDocument().getId(),c.getDocument().getFilename(),c.getChunkIndex(),c.getContent(),cosine(q,decode(c.getEmbedding())))).filter(h->h.score()>0).sorted(Comparator.comparingDouble(Hit::score).reversed()).limit(Math.min(limit,8)).toList();} public Answer answer(String question){var hits=search(question,4);if(hits.isEmpty())return new Answer("I couldn’t find sufficient information in the indexed knowledge base to answer that.",hits);String evidence=hits.stream().map(Hit::content).flatMap(c->Arrays.stream(c.split("(?<=[.!?])\\s+"))).filter(s->overlap(question,s)>0).limit(3).collect(Collectors.joining(" "));if(evidence.isBlank())evidence=hits.getFirst().content();return new Answer(evidence,hits);} private int overlap(String q,String s){int count=0;for(String w:q.toLowerCase().split("\\W+"))if(w.length()>2&&s.toLowerCase().contains(w))count++;return count;} private String encode(double[] v){return Arrays.stream(v).mapToObj(Double::toString).collect(Collectors.joining(","));} private double[] decode(String s){return Arrays.stream(s.split(",")).mapToDouble(Double::parseDouble).toArray();} private double cosine(double[] a,double[] b){double x=0;for(int i=0;i<a.length;i++)x+=a[i]*b[i];return x;} public record Hit(UUID documentId,String filename,int chunkIndex,String content,double score){} public record Answer(String answer,List<Hit> sources){} }
